import{_ as s,c as a,o as l,ah as o,ai as n}from"./chunks/framework.DUQY3pgt.js";const g=JSON.parse('{"title":"Labctl color reference","description":"","frontmatter":{},"headers":[],"relativePath":"reference/color.md","filePath":"reference/color.md","lastUpdated":1757364760000}'),c={name:"reference/color.md"};function t(i,e,d,r,p,h){return l(),a("div",null,[...e[0]||(e[0]=[o(`<h1 id="labctl-color-reference" tabindex="-1">Labctl color reference <a class="header-anchor" href="#labctl-color-reference" aria-label="Permalink to “Labctl color reference”">​</a></h1><h2 id="cli-command" tabindex="-1">CLI command <a class="header-anchor" href="#cli-command" aria-label="Permalink to “CLI command”">​</a></h2><p>The <code>labctl color</code> command allows you to run any normal shell command and add some color. Labctl will use regular expressions to search for text of interest in the output and can then highlight these using defined colors.</p><details class="details custom-block"><summary><code>labctl color --help</code></summary><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Usage: labctl color &lt;cmd&gt; ...</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Add some color to any Linux command (i.e. ssh).</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Arguments:</span></span>
<span class="line"><span>  &lt;cmd&gt; ...</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Flags:</span></span>
<span class="line"><span>  -h, --help    Show context-sensitive help.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Global Flags</span></span>
<span class="line"><span>  -d, --debug=INT          Enable debug mode.</span></span>
<span class="line"><span>      --settings=STRING    Settings yaml file.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>labctl: error: expected &quot;&lt;cmd&gt; ...&quot;</span></span></code></pre></div></details><h3 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to “Example”">​</a></h3><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>labctl color ssh 10.0.0.1</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title custom-block-title-default">TIP</p><p>When you use <code>labctl color</code> any flags should be before the <strong>color</strong> command!</p><p>Correct: <code>labctl -d color ssh 10.0.0.1</code></p><p>Wrong: <code>labctl color <span style="color:red;">-d</span> ssh 10.0.0.1</code> (-d will be interpreted as part of the ssh command)</p></div><h2 id="colors" tabindex="-1">Colors <a class="header-anchor" href="#colors" aria-label="Permalink to “Colors”">​</a></h2><p>Valid colors include: <code>black</code>, <code>red</code>, <code>green</code>, <code>yellow</code>, <code>blue</code>, <code>magenta</code>, <code>cyan</code>, <code>white</code>. You can add the following prefixes to colors: <code>hi</code> - Highlight, <code>fg</code> - Foreground, <code>bg</code> - Background</p><p>Valid styles include: <code>bold</code>, <code>faint</code>, <code>italic</code>, <code>blinkslow</code>, <code>blinkrapid</code>, <code>reversevideo</code>, <code>concealed</code>, <code>crossedout</code></p><p>You can see a list of colors on how they are displayed on your terminal by using the --test flag</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">labctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> color</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --test</span></span></code></pre></div><p><img src="`+n+'" alt="colors"></p><div class="tip custom-block"><p class="custom-block-title custom-block-title-default">TIP</p><p>The screenshot was made on Microsoft&#39;s Windows Terminal. It supports all the colors and a blinking <code>blinkrapid</code></p></div><h2 id="labctl-settings" tabindex="-1">Labctl settings <a class="header-anchor" href="#labctl-settings" aria-label="Permalink to “Labctl settings”">​</a></h2><p>See <a href="./settings">settings</a></p>',16)])])}const m=s(c,[["render",t]]);export{g as __pageData,m as default};
